def transform(grid):
    from collections import deque

    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 0]
    if not zeros:
        return g

    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)
    rh, rw = r1 - r0 + 1, c1 - c0 + 1

    twos = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    target = (sum(r for r, c in twos) / len(twos),
              sum(c for r, c in twos) / len(twos)) if twos else (r0, c0)

    def fits(r, c):
        return (0 <= r <= h - rh and 0 <= c <= w - rw and
                all(g[y][x] != 3
                    for y in range(r, r + rh)
                    for x in range(c, c + rw)))

    start = (r0, c0)
    dist = {start: 0}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p not in dist and fits(*p):
                dist[p] = dist[(r, c)] + 1
                q.append(p)

    farthest = max(dist.values())
    candidates = [p for p, d in dist.items() if d == farthest]
    dest = min(candidates, key=lambda p:
               (abs(p[0] - target[0]) + abs(p[1] - target[1]), p))

    for r, c in zeros:
        g[r][c] = 1
    for r in range(dest[0], dest[0] + rh):
        for c in range(dest[1], dest[1] + rw):
            g[r][c] = 0
    return g
